func HasProductWith(preds ...predicate.Product) predicate.ReworkIntakeItem {
	return predicate.ReworkIntakeItem(func(s *sql.Selector) {
		step := newProductStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

