// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ReworkIntakeItem) predicate.ReworkIntakeItem {
	return predicate.ReworkIntakeItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ReworkIntakeItem) predicate.ReworkIntakeItem {
	return predicate.ReworkIntakeItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ReworkIntakeItem) predicate.ReworkIntakeItem {
	return predicate.ReworkIntakeItem(sql.NotPredicates(p))
}
